//! 🧪️ Original indexed coordinate admission preserves null retry work and complete paid directory custody.
use super::*;
use crate::allocation_testing::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn debit(bank:&mut RetainedCloneGrant,work:u128,p:RetainedCloneProgress){assert!(work<=bank.maximum_items as u128);assert!(p.fits(*bank));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]
fn indexed_edit_real_null_and_directory_close_preserve_one_finite_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();assert_eq!(schema["properties"]["laws"]["const"],law["laws"]);let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let shape=&law["shape"];let mut owner=IndexedEditPlan::new(IndexedEditShape{base_len:shape["base"].as_u64().unwrap()as usize,removed:shape["removed"].as_u64().unwrap()as usize,modified:shape["modified"].as_u64().unwrap()as usize,added:shape["added"].as_u64().unwrap()as usize});let d=owner.demand().unwrap();let g=grant(d);for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=observe(||crate::effect::settle(denied,|effect|owner.advance(effect,|_,_|panic!("denied coordinate probe"))));assert_eq!(turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}
 let((turn,attempts),heap)=observe(||refuse(||crate::effect::settle(g,|effect|owner.advance(effect,|_,_|panic!("reservation must not read coordinates")))));assert_eq!(attempts,1);assert!(turn.result.is_err());assert_eq!(turn.work,u128::from(law["nullWork"].as_u64().unwrap()));assert_eq!(heap,(0,0));debit(&mut bank,turn.work,Default::default());assert_eq!(owner.demand().unwrap(),d);let(mut born,mut freed)=(0,0);let coordinate=law["coordinate"].as_u64().unwrap()as usize;
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if owner.settled(){break}let g=grant(owner.demand().unwrap());let(turn,heap)=observe(||crate::effect::settle(g,|effect|owner.advance(effect,|kind,ordinal|{assert_eq!(kind,IndexedEditKind::Removed);assert_eq!(ordinal,0);crate::RetainedWorkOutcome{result:Ok(coordinate),work:1}})));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);born+=heap.0;freed+=heap.1;}assert!(owner.ready());assert_eq!(owner.output_len().unwrap(),1);let indices=owner.entries(IndexedEditKind::Removed).unwrap().iter().map(|row|row.index).collect::<Vec<_>>();assert_eq!(serde_json::to_value(indices).unwrap(),serde_json::json!([coordinate]));
 owner.begin_close();for _ in 0..law["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let g=grant(owner.close_demand(4096).unwrap());let(turn,heap)=observe(||crate::effect::settle(g,|effect|owner.close_step(effect)));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);born+=heap.0;freed+=heap.1;}assert!(owner.terminal_is_empty());let(turn,heap)=observe(||crate::effect::settle(Default::default(),|effect|owner.close_step(effect)));assert_eq!(turn.work,u128::from(law["cachedWork"].as_u64().unwrap()));assert!(matches!(turn.result,Ok(RetainedCloneStep::Complete(p))if p==Default::default()));assert_eq!(heap,(0,0));assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(born,freed);
}
